fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let target_len = width as usize;
    
    if orig_len >= target_len {
        // No padding needed, return original
        orig
    } else {
        // Calculate how many fill characters we need
        let padding_len = target_len - orig_len;
        
        // Create result vector with capacity for all characters
        let mut result = Vec::with_capacity(target_len);
        
        // Add padding characters
        for _ in 0..padding_len {
            result.push(fillchar);
        }
        
        // Add original characters
        result.extend(orig);
        
        result
    }
}